<?php require_once __DIR__.'/config/auth.php';$jenis=$_GET['jenis']??$_POST['jenis']??'pemasukan';if(!in_array($jenis,['pemasukan','pengeluaran']))$jenis='pemasukan';$pageTitle=ucfirst($jenis);if(isset($_GET['hapus'])){$pdo->prepare("DELETE FROM transaksi WHERE id=?")->execute([(int)$_GET['hapus']]);header("Location:transaksi.php?jenis=$jenis");exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO transaksi(tanggal,jenis,kategori_id,nominal,keterangan,user_id) VALUES(?,?,?,?,?,?)")->execute([$_POST['tanggal'],$jenis,(int)$_POST['kategori_id'],(float)$_POST['nominal'],trim($_POST['keterangan']),$_SESSION['user']['id']]);header("Location:transaksi.php?jenis=$jenis");exit;}$s=$pdo->prepare("SELECT * FROM kategori WHERE jenis=? ORDER BY nama");$s->execute([$jenis]);$cats=$s->fetchAll();$tanggal=$_GET['tanggal']??'';$q=trim($_GET['q']??'');$sql="SELECT t.*,k.nama kategori FROM transaksi t JOIN kategori k ON k.id=t.kategori_id WHERE t.jenis=?";$params=[$jenis];if($tanggal){$sql.=" AND t.tanggal=?";$params[]=$tanggal;}if($q){$sql.=" AND (t.keterangan LIKE ? OR k.nama LIKE ?)";$params[]="%$q%";$params[]="%$q%";}$sql.=" ORDER BY t.tanggal DESC,t.id DESC";$s=$pdo->prepare($sql);$s->execute($params);$data=$s->fetchAll();function rpx($n){return 'Rp '.number_format($n,0,',','.');}include __DIR__.'/partials/header.php';?><div class="card p-4 mb-4"><h5>Tambah <?=ucfirst($jenis)?></h5><form method="post" class="row g-3"><input type="hidden" name="jenis" value="<?=$jenis?>"><div class="col-md-2"><label>Tanggal</label><input type="date" name="tanggal" class="form-control" value="<?=date('Y-m-d')?>" required></div><div class="col-md-3"><label>Kategori</label><select name="kategori_id" class="form-select" required><option value="">Pilih</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['nama'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Nominal</label><input type="number" name="nominal" class="form-control" min="1" required></div><div class="col-md-4"><label>Keterangan</label><input name="keterangan" class="form-control"></div><div class="col-12"><button class="btn btn-success">Simpan</button></div></form></div><div class="card p-4"><div class="d-flex justify-content-between mb-3"><h5>Data <?=ucfirst($jenis)?></h5><form class="d-flex gap-2"><input type="hidden" name="jenis" value="<?=$jenis?>"><input type="date" name="tanggal" value="<?=$tanggal?>" class="form-control"><input name="q" value="<?=htmlspecialchars($q)?>" class="form-control" placeholder="Cari"><button class="btn btn-primary">Filter</button></form></div><div class="table-responsive"><table class="table"><thead><tr><th>Tanggal</th><th>Kategori</th><th>Keterangan</th><th>Nominal</th><th>Aksi</th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=$r['tanggal']?></td><td><?=htmlspecialchars($r['kategori'])?></td><td><?=htmlspecialchars($r['keterangan']?:'-')?></td><td class="fw-bold <?=$jenis==='pemasukan'?'income':'expense'?>"><?=rpx($r['nominal'])?></td><td><a class="btn btn-sm btn-outline-danger" href="?jenis=<?=$jenis?>&hapus=<?=$r['id']?>" onclick="return confirm('Hapus transaksi?')">Hapus</a></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/partials/footer.php';?>